//! Parity of the hook (promptguard.py) and hookinstall.py with fixtures generated by running the Python code
//! (tools/gen_fixtures_hook.py -> tests/fixtures/hook.json, hookinstall.json).

use cu_core::hook::{evaluate, resolve_config_dir};
use cu_core::hookinstall::{self, HookProfile};
use serde_json::Value;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};

const FAKE_EXE: &str = "C:\\cu-fixture\\claude-usage.exe";

fn load(name: &str) -> Vec<Value> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(format!("{name}.json"));
    let text = fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    match serde_json::from_str(&text).expect("fixture JSON") {
        Value::Array(a) => a,
        _ => panic!("fixture {name} is not a list"),
    }
}

fn close(a: f64, b: f64) -> bool {
    a == b || (a - b).abs() <= 1e-9_f64.max(1e-12 * a.abs().max(b.abs()))
}

/// Semantic JSON equality (5 == 5.0), objects compared in key ORDER too.
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => match (x.as_i64(), y.as_i64()) {
            (Some(i), Some(j)) => i == j,
            _ => close(
                x.as_f64().unwrap_or(f64::NAN),
                y.as_f64().unwrap_or(f64::NAN),
            ),
        },
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| json_eq(p, q))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .zip(y.iter())
                    .all(|((k1, v1), (k2, v2))| k1 == k2 && json_eq(v1, v2))
        }
        _ => a == b,
    }
}

struct Tokens {
    home: String,
    cwd: String,
    drive: String,
    existing_exe: String,
}

impl Tokens {
    fn s(&self, s: &str) -> String {
        s.replace("{HOME}", &self.home)
            .replace("{CWD}", &self.cwd)
            .replace("{DRIVE}", &self.drive)
            .replace("{EXISTING_EXE}", &self.existing_exe)
    }
    fn v(&self, v: &Value) -> Value {
        match v {
            Value::String(s) => Value::String(self.s(s)),
            Value::Array(a) => Value::Array(a.iter().map(|x| self.v(x)).collect()),
            Value::Object(o) => {
                Value::Object(o.iter().map(|(k, x)| (self.s(k), self.v(x))).collect())
            }
            other => other.clone(),
        }
    }
}

fn tokens(root: &Path) -> Tokens {
    let cwd = std::env::current_dir()
        .unwrap()
        .to_string_lossy()
        .to_string();
    let drive = cwd[..2].to_string();
    let existing = root.join("existing").join("claude-usage.exe");
    fs::create_dir_all(existing.parent().unwrap()).unwrap();
    fs::write(&existing, b"x").unwrap();
    Tokens {
        home: root.join("home").to_string_lossy().to_string(),
        cwd,
        drive,
        existing_exe: existing.to_string_lossy().to_string(),
    }
}

#[test]
fn hook_parity() {
    let tmp = tempfile::tempdir().unwrap();
    let t = tokens(tmp.path());
    let cases = load("hook");
    let mut fails = Vec::new();
    for c in &cases {
        let name = c["name"].as_str().unwrap();
        let i = &c["input"];
        let cache: Option<Value> = if let Some(text) = i["cache_text"].as_str() {
            serde_json::from_str(text).ok()
        } else if i["cache"].is_null() {
            None
        } else {
            Some(t.v(&i["cache"]))
        };
        let env = i["env_config_dir"].as_str().map(|s| OsString::from(t.s(s)));
        let cfg = resolve_config_dir(env, Path::new(&t.home));
        let got = evaluate(cache.as_ref(), i["now"].as_f64().unwrap(), &cfg);
        if c["deviation"].as_bool() == Some(true) {
            if got.code != 0 {
                fails.push(format!(
                    "{name}: deviation case must fail open, got {got:?}"
                ));
            }
            continue;
        }
        let e = &c["expected"];
        let want_err = e["stderr"].as_str();
        if i64::from(got.code) != e["code"].as_i64().unwrap() || got.stderr.as_deref() != want_err {
            fails.push(format!("{name}\n  expected={e}\n  got={got:?}"));
        }
    }
    assert!(
        fails.is_empty(),
        "hook: {}/{} cases differ from Python:\n{}",
        fails.len(),
        cases.len(),
        fails.join("\n")
    );
    println!("hook: {} cases OK", cases.len());
}

fn write_input(p: &Path, s: &Value, t: &Tokens) {
    if let Some(text) = s["settings_text"].as_str() {
        fs::write(p, text).unwrap();
    } else if !s["settings"].is_null() {
        fs::write(
            p,
            serde_json::to_string_pretty(&t.v(&s["settings"])).unwrap(),
        )
        .unwrap();
    }
}

fn pairs_json<T: Into<Value>>(v: Vec<(String, T)>) -> Value {
    Value::Array(
        v.into_iter()
            .map(|(n, x)| Value::Array(vec![Value::from(n), x.into()]))
            .collect(),
    )
}

#[test]
fn hookinstall_parity() {
    let cases = load("hookinstall");
    let exe = Path::new(FAKE_EXE);
    let mut fails = Vec::new();
    for (idx, c) in cases.iter().enumerate() {
        let name = c["name"].as_str().unwrap();
        let tmp = tempfile::tempdir().unwrap();
        let t = tokens(tmp.path());
        let base = tmp.path().join("hi");
        let mut profiles = Vec::new();
        let mut files = Vec::new();
        for (i, s) in c["input"]["profiles"]
            .as_array()
            .unwrap()
            .iter()
            .enumerate()
        {
            let d = base.join(format!("prof{i}"));
            if s["no_dir"].as_bool() != Some(true) {
                fs::create_dir_all(&d).unwrap();
            }
            let f = d.join("settings.json");
            write_input(&f, s, &t);
            if let Some(b) = s["bak_text"].as_str() {
                fs::write(d.join("settings.json.claude-usage.bak"), b).unwrap();
            }
            profiles.push(HookProfile::new(s["name"].as_str().unwrap(), d));
            files.push(f);
        }
        let deviation = c["deviation"].as_bool() == Some(true);
        let exp = &c["expected"];
        let mut op_fail = None;
        for (k, op) in c["input"]["ops"].as_array().unwrap().iter().enumerate() {
            let want = &exp["results"][k];
            let raised = want.get("raises").is_some();
            let got: Value = match op.as_str().unwrap() {
                "install" => pairs_json(hookinstall::install(&profiles, exe)),
                "uninstall" => pairs_json(hookinstall::uninstall(&profiles)),
                "status" => pairs_json(
                    hookinstall::status(&profiles)
                        .into_iter()
                        .map(|(n, s)| (n, s.map_or(Value::Null, Value::Bool)))
                        .collect(),
                ),
                "repair" => {
                    hookinstall::repair_unchecked(&profiles, exe, &mut |_| {});
                    Value::Null
                }
                other => panic!("unknown op {other}"),
            };
            if raised {
                break; // Python raised: Rust only has to not panic and leave the file alone (checked below)
            }
            if !deviation && !json_eq(&got, want) {
                op_fail = Some(format!("op #{k} {op}: expected {want} got {got}"));
                break;
            }
        }
        let mut bad = op_fail;
        for (i, f) in files.iter().enumerate() {
            let want = &exp["files"][i];
            let dir = f.parent().unwrap();
            let bak = dir.join("settings.json.claude-usage.bak");
            let rs = fs::read_to_string(f).ok();
            if deviation {
                // R1: python rewrote a hook whose exe exists, rust must leave everything as it was.
                let input = &c["input"]["profiles"][i];
                let same = rs
                    .as_deref()
                    .and_then(|s| serde_json::from_str::<Value>(s).ok())
                    == Some(t.v(&input["settings"]))
                    && !bak.exists();
                if !same {
                    bad.get_or_insert(format!("deviation: file changed: {rs:?}"));
                }
                continue;
            }
            if want["exists"].as_bool() != Some(rs.is_some()) {
                bad.get_or_insert(format!("profile {i}: exists mismatch, want {want}"));
                continue;
            }
            if let Some(rs) = &rs {
                if let Some(wj) = want.get("json") {
                    match serde_json::from_str::<Value>(rs) {
                        Ok(gj) if json_eq(&gj, wj) => {}
                        _ => {
                            bad.get_or_insert(format!(
                                "profile {i}: file json differs\n  want {wj}\n  got  {rs}"
                            ));
                        }
                    }
                } else if want["text"].as_str() != Some(rs.as_str()) {
                    bad.get_or_insert(format!("profile {i}: raw text differs, got {rs:?}"));
                }
            }
            if want["bak_exists"].as_bool() != Some(bak.exists()) {
                bad.get_or_insert(format!(
                    "profile {i}: bak exists mismatch, want {}",
                    want["bak_exists"]
                ));
            } else if bak.exists() {
                // Python's write_text on Windows wrote CRLF into files it created itself (known deviation).
                let b = fs::read_to_string(&bak).unwrap().replace("\r\n", "\n");
                let w = want["bak_text"].as_str().map(|s| s.replace("\r\n", "\n"));
                if w.as_deref() != Some(b.as_str()) {
                    bad.get_or_insert(format!("profile {i}: bak text differs, got {b:?}"));
                }
            }
        }
        if let Some(b) = bad {
            fails.push(format!("#{idx} {name}: {b}"));
        }
    }
    assert!(
        fails.is_empty(),
        "hookinstall: {}/{} cases differ from Python:\n{}",
        fails.len(),
        cases.len(),
        fails.join("\n")
    );
    println!("hookinstall: {} cases OK", cases.len());
}

// ---------------------------------------------------------------- R1 repair policy (intentional deviation)

fn stale_profile(dir: &Path, cmd: &str) -> (HookProfile, PathBuf) {
    fs::create_dir_all(dir).unwrap();
    let f = dir.join("settings.json");
    let doc = serde_json::json!({"hooks": {"UserPromptSubmit": [{"hooks": [{"type": "command", "command": cmd}]}]}});
    fs::write(&f, serde_json::to_string_pretty(&doc).unwrap()).unwrap();
    (HookProfile::new("p", dir), f)
}

#[test]
fn repair_is_gated_by_flag_and_debug_build() {
    let tmp = tempfile::tempdir().unwrap();
    let (p, f) = stale_profile(&tmp.path().join("a"), "\"C:\\gone\\claude-usage.exe\" hook");
    let before = fs::read_to_string(&f).unwrap();
    let mut logged = Vec::new();
    // no_repair always wins
    let r = hookinstall::repair(
        std::slice::from_ref(&p),
        Path::new(FAKE_EXE),
        true,
        &mut |m| logged.push(m.to_string()),
    );
    assert!(r.is_empty() && logged.is_empty());
    assert_eq!(fs::read_to_string(&f).unwrap(), before);
    // debug builds (this test profile) never repair; release builds do
    let r = hookinstall::repair(&[p], Path::new(FAKE_EXE), false, &mut |m| {
        logged.push(m.to_string())
    });
    if cfg!(debug_assertions) {
        assert!(r.is_empty() && logged.is_empty());
        assert_eq!(fs::read_to_string(&f).unwrap(), before);
    } else {
        assert_eq!(r, vec!["p".to_string()]);
        assert!(logged[0].contains("hook repaired"));
    }
}

#[test]
fn repair_unchecked_rewrites_only_when_old_exe_is_missing() {
    let tmp = tempfile::tempdir().unwrap();
    let new_exe = tmp.path().join("new").join("claude-usage.exe");
    let old_exe = tmp.path().join("old").join("claude-usage.exe");
    fs::create_dir_all(old_exe.parent().unwrap()).unwrap();
    fs::write(&old_exe, b"x").unwrap();

    // old exe still exists -> left alone, nothing logged
    let (p, f) = stale_profile(&tmp.path().join("a"), &hookinstall::command(&old_exe));
    let before = fs::read_to_string(&f).unwrap();
    let mut logged = Vec::new();
    let r = hookinstall::repair_unchecked(&[p], &new_exe, &mut |m| logged.push(m.to_string()));
    assert!(r.is_empty() && logged.is_empty());
    assert_eq!(fs::read_to_string(&f).unwrap(), before);

    // old exe deleted -> rewritten to the new command, logged, no backup made
    fs::remove_file(&old_exe).unwrap();
    let (p, f) = stale_profile(&tmp.path().join("b"), &hookinstall::command(&old_exe));
    let r = hookinstall::repair_unchecked(&[p], &new_exe, &mut |m| logged.push(m.to_string()));
    assert_eq!(r, vec!["p".to_string()]);
    assert_eq!(logged.len(), 1);
    let doc: Value = serde_json::from_str(&fs::read_to_string(&f).unwrap()).unwrap();
    assert_eq!(
        doc["hooks"]["UserPromptSubmit"][0]["hooks"][0]["command"],
        Value::from(hookinstall::command(&new_exe))
    );
    assert!(!tmp
        .path()
        .join("b")
        .join("settings.json.claude-usage.bak")
        .exists());
}

#[test]
fn command_exe_parsing() {
    use hookinstall::command_exe;
    assert_eq!(
        command_exe("\"C:\\a b\\claude-usage.exe\" hook"),
        Some("C:\\a b\\claude-usage.exe")
    );
    assert_eq!(command_exe("\"py.exe\" \"main.py\" hook"), Some("py.exe"));
    assert_eq!(
        command_exe("C:\\a b\\claude-usage.exe hook  "),
        Some("C:\\a b\\claude-usage.exe")
    );
    assert_eq!(command_exe(" hook"), None);
    assert_eq!(command_exe("\"unterminated hook"), None);
}
